<?php
require_once __DIR__ . '/../config/db.php';
require_once __DIR__ . '/admincheck_role.php';
require_once __DIR__ . '/../config/permissions.php';
if (!isSuperAdmin()) { http_response_code(403); exit('Only Super Admin can manage Access Control.'); }

$roles=getAllRoles($conn); $permissions=getAllPermissions($conn); $modules=getAllModules();
$selectedRoleId=(int)($_POST['role_id']??$_GET['role_id']??($roles[1]['id']??0));
$selectedRole=null; foreach($roles as $role)if((int)$role['id']===$selectedRoleId)$selectedRole=$role;
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    ems_verify_csrf();
    if(!$selectedRole)$error='Please select a valid role.';
    elseif($selectedRole['role_name']==='Super Admin')$error='Super Admin always has full access and cannot be restricted.';
    else{
        $submitted=$_POST['access']??[];$clean=[];$validModules=array_keys($modules);$validPermissions=array_column($permissions,'permission_slug');
        foreach($submitted as $module=>$items){if(!in_array($module,$validModules,true)||!is_array($items))continue;$clean[$module]=array_values(array_intersect(array_keys($items),$validPermissions));}
        if(saveRolePermissions($conn,$selectedRoleId,$clean))$message='Access permissions saved successfully for '.$selectedRole['role_name'].'.';else$error='Permissions could not be saved.';
    }
}
$current=$selectedRole?getRolePermissions($conn,$selectedRoleId):[];
function checkedAccess(array $current,string $module,string $permission):string{return in_array($permission,$current[$module]??[],true)?'checked':'';}
?>
