<?php if($selectedRole):?><form method="post" class="access-card p-4"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="role_id" value="<?=$selectedRoleId?>"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-3"><div><h5 class="mb-1"><?=htmlspecialchars($selectedRole['role_name'])?> Permissions</h5><small class="text-muted">View, Add, Edit, Delete, Approve and Export can be controlled separately.</small></div><?php if($selectedRole['role_name']!=='Super Admin'):?><div class="d-flex gap-2"><button type="button" class="btn btn-outline-primary btn-sm" id="selectAll">Select All</button><button type="button" class="btn btn-outline-secondary btn-sm" id="clearAll">Clear All</button></div><?php endif;?></div>
<?php foreach($modules as $moduleKey=>$moduleName):?><div class="module-row"><div class="row align-items-center g-3"><div class="col-lg-3"><strong><i class="fa fa-folder-open text-primary me-2"></i><?=htmlspecialchars($moduleName)?></strong></div><div class="col-lg-9"><div class="permission-grid"><?php foreach($permissions as $permission):?><?php $slug=$permission['permission_slug'];?><label class="permission-box"><input type="checkbox" class="form-check-input me-1 access-check" name="access[<?=htmlspecialchars($moduleKey)?>][<?=htmlspecialchars($slug)?>]" value="1" <?= $selectedRole['role_name']==='Super Admin'?'checked disabled':checkedAccess($current,$moduleKey,$slug) ?>><span><?=htmlspecialchars($permission['permission_name'])?></span></label><?php endforeach;?></div></div></div></div><?php endforeach;?>
<?php if($selectedRole['role_name']!=='Super Admin'):?><div class="d-flex justify-content-end pt-4"><button class="btn btn-primary btn-lg px-5"><i class="fa fa-save me-2"></i>Save Access</button></div><?php else:?><div class="alert alert-info mt-4 mb-0"><i class="fa fa-lock me-2"></i>Super Admin automatically has every permission.</div><?php endif;?></form><?php endif;?></main></div>
<script>const sidebar=document.getElementById('sidebar'),backdrop=document.getElementById('sidebarBackdrop');document.getElementById('sidebarToggle').onclick=()=>{sidebar.classList.toggle('open');backdrop.classList.toggle('show')};document.getElementById('selectAll')?.addEventListener('click',()=>document.querySelectorAll('.access-check').forEach(x=>x.checked=true));document.getElementById('clearAll')?.addEventListener('click',()=>document.querySelectorAll('.access-check').forEach(x=>x.checked=false));</script></body></html>
